/**
 * The four faces `src/design/tokens.ts` names for the mono stack, at the two
 * weights the typography table actually uses, subset to Latin and basic
 * punctuation and compressed to WOFF2. Hand-generated once from this
 * machine's installed `noto-fonts` and `fonts-dejavu` packages via
 * `subset-font`, and committed as a plain data module rather than a build
 * step, because these four faces never change on their own the way
 * `DESIGN.md`'s tokens do.
 */

export interface FontFace {
  readonly family: string
  readonly weight: string
  readonly base64: string
}

const NOTO_SANS_MONO_400 =
  ''

const NOTO_SANS_MONO_700 =
  ''

const DEJAVU_SANS_MONO_400 =
  ''

const DEJAVU_SANS_MONO_700 =
  ''

/** Ordered as `src/design/tokens.ts`'s typography table declares the weights. */
export const FONT_FACES: readonly FontFace[] = [
  { family: 'Noto Sans Mono', weight: '400', base64: NOTO_SANS_MONO_400 },
  { family: 'Noto Sans Mono', weight: '700', base64: NOTO_SANS_MONO_700 },
  { family: 'DejaVu Sans Mono', weight: '400', base64: DEJAVU_SANS_MONO_400 },
  { family: 'DejaVu Sans Mono', weight: '700', base64: DEJAVU_SANS_MONO_700 },
]
